//! Conversion from a pushdown automaton in restricted normal form (RNF) to a
//! context-free grammar (`PDAtoCFG`, Slide13 pages 20 to 27).

use crate::fsm::{StateId, SymbolId, limit_exceeded};
use crate::grammar::{Grammar, Production, Symbol};
use crate::message::Message;
use crate::pda::Pda;
use serde::Serialize;
use std::collections::BTreeMap;

/// Maximum number of grammar rules that `pda_to_cfg` may produce.
pub const MAX_PDA_CFG_RULES: usize = 20_000;

/// Metadata for a variable `V_{from}g{k}p{to}` generated by `pda_to_cfg`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct CfgVariable {
    pub name: String,
    pub from: StateId,
    pub stack: Option<String>,
    pub to: StateId,
}

/// One step in the `pda_to_cfg` trace.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct PdaCfgStep {
    pub added: Vec<Production>,
    pub message: Message,
}

/// The result of `pda_to_cfg`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct PdaToCfg {
    pub grammar: Grammar,
    pub variables: Vec<CfgVariable>,
    pub steps: Vec<PdaCfgStep>,
}

/// Returns whether `c` is a single character that `GrammarParser` reads back as
/// `Symbol::Terminal(c)`.
fn is_readable_terminal_char(c: char) -> bool {
    !c.is_ascii_uppercase()
        && !c.is_whitespace()
        && !matches!(c, '<' | '[' | '|' | '\\' | 'ε' | 'λ' | '^')
}

/// Validated RNF parameters extracted by `rnf_shape_error`.
struct RnfInfo {
    s_prime: StateId,
    s: StateId,
    a: StateId,
    marker_id: SymbolId,
    terminal_chars: Vec<char>,
}

/// Checks the six RNF input requirements of Decision 1 in exact order.
fn rnf_shape_error(pda: &Pda) -> Result<RnfInfo, Message> {
    // (a) No start state.
    let s_prime = pda
        .start
        .ok_or_else(|| Message::new("pda_cfg.no_start_state"))?;

    // (b) The start state `s'` must have:
    // - no incoming transition (`t.to == s'`)
    // - not in `pda.accepting`
    // - exactly one outgoing transition (`t.from == s'`), with `read: None`, `pop: []`,
    //   and `push` of length 1 (the marker `#`).
    let bad_start = || Message::new("pda_cfg.bad_start").with("state", s_prime.0);
    if pda.accepting.contains(&s_prime) {
        return Err(bad_start());
    }
    if pda.transitions.iter().any(|t| t.to == s_prime) {
        return Err(bad_start());
    }
    let mut from_start = pda.transitions.iter().filter(|t| t.from == s_prime);
    let Some(start_trans) = from_start.next() else {
        return Err(bad_start());
    };
    if from_start.next().is_some()
        || start_trans.read.is_some()
        || !start_trans.pop.is_empty()
        || start_trans.push.len() != 1
    {
        return Err(bad_start());
    }
    let marker_id = start_trans.push[0];
    let s = start_trans.to;

    // (c) Exactly one accepting state `a`.
    if pda.accepting.len() != 1 {
        return Err(Message::new("pda_cfg.not_one_accepting").with("count", pda.accepting.len()));
    }
    let a = pda.accepting[0];

    // (d) Every transition into `a` reads ε, pops `[marker_id]` and pushes nothing.
    for t in &pda.transitions {
        if t.to == a && (t.read.is_some() || t.pop.as_slice() != [marker_id] || !t.push.is_empty())
        {
            return Err(Message::new("pda_cfg.bad_accept").with("from", t.from.0));
        }
    }

    // (e) Every transition not from `s'` pops exactly one symbol.
    for t in &pda.transitions {
        if t.from != s_prime && t.pop.len() != 1 {
            return Err(Message::new("pda_cfg.not_single_pop")
                .with("from", t.from.0)
                .with("to", t.to.0));
        }
    }

    // (f) Every input symbol is one character that the grammar parser reads as a terminal.
    let mut terminal_chars = Vec::with_capacity(pda.input.len());
    for sym_name in pda.input.names() {
        let mut chars = sym_name.chars();
        let Some(ch) = chars.next() else {
            return Err(
                Message::new("pda_cfg.terminal_not_readable").with("symbol", sym_name.as_str())
            );
        };
        if chars.next().is_some() || !is_readable_terminal_char(ch) {
            return Err(
                Message::new("pda_cfg.terminal_not_readable").with("symbol", sym_name.as_str())
            );
        }
        terminal_chars.push(ch);
    }

    Ok(RnfInfo {
        s_prime,
        s,
        a,
        marker_id,
        terminal_chars,
    })
}

fn var_name(from: StateId, stack: Option<SymbolId>, to: StateId) -> String {
    match stack {
        Some(sym) => format!("V_{}g{}p{}", from.0, sym.0, to.0),
        None => format!("V_{}gep{}", from.0, to.0),
    }
}

/// Converts a pushdown automaton in restricted normal form (RNF) to an equivalent
/// context-free grammar with a step-by-step trace.
pub fn pda_to_cfg(pda: &Pda) -> Result<PdaToCfg, Message> {
    let info = rnf_shape_error(pda)?;

    // Active states K = all states except s', in ascending StateId order.
    let active_states: Vec<StateId> = pda
        .states
        .iter()
        .copied()
        .filter(|&q| q != info.s_prime)
        .collect();
    let m = active_states.len() as u64;

    // Decision 5: Check size limit BEFORE building any rule.
    // Rule count = 1 + (k - 1) + sum over transitions not from s' of (k - 1)^max(n, 1).
    let limit_err = || limit_exceeded("rules", MAX_PDA_CFG_RULES);
    let mut total_rules = 1u64.checked_add(m).ok_or_else(limit_err)?;
    for t in &pda.transitions {
        if t.from == info.s_prime {
            continue;
        }
        let exp = u32::try_from(t.push.len().max(1)).map_err(|_| limit_err())?;
        let term = m.checked_pow(exp).ok_or_else(limit_err)?;
        total_rules = total_rules.checked_add(term).ok_or_else(limit_err)?;
        if total_rules > MAX_PDA_CFG_RULES as u64 {
            return Err(limit_err());
        }
    }

    let total_usize = usize::try_from(total_rules).map_err(|_| limit_err())?;
    let mut all_rules = Vec::with_capacity(total_usize);
    let mut steps = Vec::new();
    // Track variables by sort key `(from, stack_id_with_epsilon_last, to)`.
    let mut var_map: BTreeMap<(StateId, u16, StateId), CfgVariable> = BTreeMap::new();

    let mut record_var = |from: StateId, stack: Option<SymbolId>, to: StateId| -> String {
        let name = var_name(from, stack, to);
        let sort_stack = stack.map_or(u16::MAX, |id| id.0);
        var_map
            .entry((from, sort_stack, to))
            .or_insert_with(|| CfgVariable {
                name: name.clone(),
                from,
                stack: stack
                    .and_then(|id| pda.stack.name(id))
                    .map(ToString::to_string),
                to,
            });
        name
    };

    // Step 1: Start rule `S -> V_{s}g{marker_id}p{a}`.
    let start_rhs = record_var(info.s, Some(info.marker_id), info.a);
    let start_rule = Production::new("S", vec![Symbol::NonTerminal(start_rhs)]);
    all_rules.push(start_rule.clone());
    steps.push(PdaCfgStep {
        added: vec![start_rule],
        message: Message::new("pda_cfg.start"),
    });

    // Step 2: `<q, ε, q> -> ε` for each `q` in K in ascending StateId order.
    let mut empty_rules = Vec::with_capacity(active_states.len());
    for &q in &active_states {
        let head = record_var(q, None, q);
        let rule = Production::new(head, Vec::new());
        all_rules.push(rule.clone());
        empty_rules.push(rule);
    }
    steps.push(PdaCfgStep {
        added: empty_rules,
        message: Message::new("pda_cfg.empty").with("count", active_states.len()),
    });

    // Step 3+: One block for each transition not from s' in Pda::new sorted order.
    for t in &pda.transitions {
        if t.from == info.s_prime {
            continue;
        }
        let q = t.from;
        let r = t.to;
        let gamma = t.pop[0];
        let term_sym = t
            .read
            .and_then(|id| info.terminal_chars.get(usize::from(id.0)).copied())
            .map(Symbol::Terminal);

        if t.push.is_empty() {
            // Case A: pushes nothing. For every w in K ascending:
            // `<q, γ, w> -> c <r, ε, w>`
            let mut step_rules = Vec::with_capacity(active_states.len());
            for &w in &active_states {
                let head = record_var(q, Some(gamma), w);
                let rhs_var = record_var(r, None, w);
                let mut body = Vec::with_capacity(2);
                if let Some(ref c) = term_sym {
                    body.push(c.clone());
                }
                body.push(Symbol::NonTerminal(rhs_var));
                let rule = Production::new(head, body);
                all_rules.push(rule.clone());
                step_rules.push(rule);
            }
            steps.push(PdaCfgStep {
                added: step_rules,
                message: Message::new("pda_cfg.push_none")
                    .with("from", q.0)
                    .with("to", r.0),
            });
        } else {
            // Case B: pushes n >= 1 symbols.
            // Enumerate tuples (v_1, ..., v_n) in K^n with v_1 slowest and v_n fastest:
            // `<q, γ, v_n> -> c <r, γ_1, v_1> <v_1, γ_2, v_2> ... <v_{n-1}, γ_n, v_n>`
            let n = t.push.len();
            let k_len = active_states.len();
            let mut step_rules = Vec::new();
            if k_len > 0 {
                let mut indices = vec![0usize; n];
                loop {
                    let vn = active_states[indices[n - 1]];
                    let head = record_var(q, Some(gamma), vn);
                    let mut body = Vec::with_capacity(n + 1);
                    if let Some(ref c) = term_sym {
                        body.push(c.clone());
                    }
                    let mut prev_state = r;
                    for (i, &idx) in indices.iter().enumerate() {
                        let next_state = active_states[idx];
                        let nt = record_var(prev_state, Some(t.push[i]), next_state);
                        body.push(Symbol::NonTerminal(nt));
                        prev_state = next_state;
                    }
                    let rule = Production::new(head, body);
                    all_rules.push(rule.clone());
                    step_rules.push(rule);

                    // Increment tuple indices from rightmost (fastest, v_n) to leftmost (slowest, v_1).
                    let mut pos = n;
                    while pos > 0 {
                        pos -= 1;
                        indices[pos] += 1;
                        if indices[pos] < k_len {
                            break;
                        }
                        indices[pos] = 0;
                    }
                    if pos == 0 && indices[0] == 0 {
                        break;
                    }
                }
            }
            steps.push(PdaCfgStep {
                added: step_rules,
                message: Message::new("pda_cfg.push")
                    .with("from", q.0)
                    .with("to", r.0)
                    .with("pushes", n),
            });
        }
    }

    let variables: Vec<CfgVariable> = var_map.into_values().collect();
    let grammar = Grammar::new("S", all_rules);

    Ok(PdaToCfg {
        grammar,
        variables,
        steps,
    })
}
